import React, { useEffect, useRef, useState, useMemo } from 'react';
import { ControlPanel } from './ControlPanel';
import { faceLandmarkerService } from './faceLandmarker';
import { getFaceTriangles } from './triangulation';
import { type AppState, type Point3D, getRandomPrompt } from './types';
import { Loader2, User, ImagePlus, AlertTriangle, X, Info, Sparkles, Video } from 'lucide-react';
import { FaceLandmarker, type FaceLandmarkerResult } from '@mediapipe/tasks-vision';
import { Flow } from 'flow-sdk';
import { Input, Output, Conversion, Mp4OutputFormat, BufferTarget, BlobSource, ALL_FORMATS } from 'mediabunny';

const FEATURE_INDICES = {
  leftEye: [33, 7, 163, 144, 145, 153, 154, 155, 133, 173, 157, 158, 159, 160, 161, 246],
  rightEye: [362, 382, 381, 380, 374, 373, 390, 249, 263, 466, 388, 387, 386, 385, 384, 398],
  lips: [78, 191, 80, 81, 82, 13, 312, 311, 310, 415, 308, 324, 318, 402, 317, 14, 87, 178, 88, 95],
  oval: [10, 338, 297, 332, 284, 251, 389, 356, 454, 323, 361, 288, 397, 365, 379, 378, 400, 377, 152, 148, 176, 149, 150, 136, 172, 58, 132, 93, 234, 127, 162, 21, 54, 103, 67, 109]
};

const SMOOTHING_FACTOR = 0.35;

/** Helper to draw the wireframe mesh lines (Stage 1 only) */
const drawWireframe = (ctx: CanvasRenderingContext2D, landmarks: Point3D[], width: number, height: number, isMirrored: boolean, triangles: number[][]) => {
  ctx.save();
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.4)'; // Visibility for Stage 1
  ctx.lineWidth = 0.5;
  const getX = (val: number) => (isMirrored ? (1 - val) : val) * width;
  const getY = (val: number) => val * height;

  for (const tri of triangles) {
    const [i, j, k] = tri;
    ctx.beginPath();
    ctx.moveTo(getX(landmarks[i].x), getY(landmarks[i].y));
    ctx.lineTo(getX(landmarks[j].x), getY(landmarks[j].y));
    ctx.lineTo(getX(landmarks[k].x), getY(landmarks[k].y));
    ctx.closePath();
    ctx.stroke();
  }
  ctx.restore();
};

export default function App() {
  const [state, setState] = useState<AppState>({
    isLoading: true,
    status: 'Ready',
    swapEyes: true,
    swapMouth: true,
    backgroundMode: 'media',
    faceOpacity: 1.0,
    blendMode: 'source-over',
    maskBlur: 5,
    hasMedia: false,
    mediaFaceWarning: false,
    isGenerating: false,
    isRecording: false,
    isProcessing: false,
    recordMic: false,
    recordSystem: true,
    faceDetectionConfidence: 0.3,
    facePresenceConfidence: 0.3,
    faceTrackingConfidence: 0.3,
    showOnboarding: true,
  });

  const stateRef = useRef<AppState>(state);
  useEffect(() => { stateRef.current = state; }, [state]);

  const webcamRef = useRef<HTMLVideoElement>(null);
  const uploadedMediaRef = useRef<HTMLImageElement | HTMLVideoElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const warpCanvasRef = useRef<HTMLCanvasElement | null>(null);
  const maskCanvasRef = useRef<HTMLCanvasElement | null>(null);

  const webcamLandmarkerRef = useRef<any>(null);
  const mediaLandmarkerRef = useRef<any>(null);
  const mediaLandmarkerModeRef = useRef<'IMAGE' | 'VIDEO'>('IMAGE');

  const flowStreamRef = useRef<any>(null);
  const webcamCanvasRef = useRef<HTMLCanvasElement | null>(null);
  const requestRef = useRef<number | undefined>(undefined);
  const lastWebcamTimeRef = useRef(-1);
  const lastMediaTimeRef = useRef(-1);

  const lastWebcamResultRef = useRef<FaceLandmarkerResult | null>(null);
  const lastMediaResultRef = useRef<FaceLandmarkerResult | null>(null);
  const smoothedWebcamMarksRef = useRef<Point3D[]>([]);
  const smoothedMediaMarksRef = useRef<Point3D[]>([]);

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const recordedChunksRef = useRef<Blob[]>([]);

  const baseTriangles = useMemo(() => getFaceTriangles(), []);

  // Define helpers as local functions for hoisting stability within component
  function smoothMarks(newMarks: Point3D[], ref: React.MutableRefObject<Point3D[]>) {
    if (ref.current.length === 0) { ref.current = [...newMarks]; return newMarks; }
    ref.current = newMarks.map((m, i) => {
      const prev = ref.current[i]; if (!prev) return m;
      return { x: prev.x + (m.x - prev.x) * SMOOTHING_FACTOR, y: prev.y + (m.y - prev.y) * SMOOTHING_FACTOR, z: prev.z + (m.z - prev.z) * SMOOTHING_FACTOR };
    });
    return ref.current;
  }

  function calculateCentroid(landmarks: Point3D[], indices: number[]) {
    let cx = 0, cy = 0, cz = 0;
    indices.forEach(idx => { cx += landmarks[idx].x; cy += landmarks[idx].y; cz += landmarks[idx].z; });
    return { x: cx / indices.length, y: cy / indices.length, z: cz / indices.length };
  }

  function drawAffineFaceSwap(
    ctx: CanvasRenderingContext2D, sourceVideo: CanvasImageSource, sourceMarks: Point3D[], targetMarks: Point3D[],
    srcW: number, srcH: number, dstW: number, dstH: number, isTargetMirrored: boolean, isSourceMirrored: boolean,
    swapEyes: boolean, swapMouth: boolean, opacity: number, blendMode: GlobalCompositeOperation, maskBlur: number
  ) {
    if (!warpCanvasRef.current) warpCanvasRef.current = document.createElement('canvas');
    if (!maskCanvasRef.current) maskCanvasRef.current = document.createElement('canvas');
    const warpCanvas = warpCanvasRef.current;
    const maskCanvas = maskCanvasRef.current;
    if (warpCanvas.width !== dstW) { warpCanvas.width = dstW; warpCanvas.height = dstH; maskCanvas.width = dstW; maskCanvas.height = dstH; }
    const wCtx = warpCanvas.getContext('2d')!;
    const mCtx = maskCanvas.getContext('2d')!;
    wCtx.clearRect(0, 0, dstW, dstH);
    mCtx.clearRect(0, 0, dstW, dstH);

    const getTargetX = (val: number) => (isTargetMirrored ? (1 - val) : val) * dstW;
    const getTargetY = (val: number) => val * dstH;
    const getSourceX = (val: number) => (isSourceMirrored ? (1 - val) : val) * srcW;
    const getSourceY = (val: number) => val * srcH;

    const activeTriangles = [...baseTriangles];
    const sourceMutated = [...sourceMarks];
    const targetMutated = [...targetMarks];

    const addFeatureSwap = (indices: number[]) => {
      const sIdx = sourceMutated.length;
      sourceMutated.push(calculateCentroid(sourceMarks, indices));
      targetMutated.push(calculateCentroid(targetMarks, indices));
      for (let i = 0; i < indices.length; i++) activeTriangles.push([sIdx, indices[i], indices[(i + 1) % indices.length]]);
    };

    if (swapEyes) { addFeatureSwap(FEATURE_INDICES.leftEye); addFeatureSwap(FEATURE_INDICES.rightEye); }
    if (swapMouth) addFeatureSwap(FEATURE_INDICES.lips);

    mCtx.fillStyle = 'white'; mCtx.beginPath();
    FEATURE_INDICES.oval.forEach((idx, i) => { const tx = getTargetX(targetMarks[idx].x), ty = getTargetY(targetMarks[idx].y); if (i === 0) mCtx.moveTo(tx, ty); else mCtx.lineTo(tx, ty); });
    mCtx.closePath(); mCtx.fill();

    if (maskBlur > 0) {
      mCtx.save(); mCtx.clip(); mCtx.globalCompositeOperation = 'destination-out';
      mCtx.filter = `blur(${maskBlur}px)`; mCtx.lineWidth = maskBlur * 5; mCtx.stroke();
      mCtx.filter = `blur(${maskBlur / 4}px)`; mCtx.lineWidth = maskBlur * 1.5; mCtx.stroke(); mCtx.restore();
    }

    for (const tri of activeTriangles) {
      const [i, j, k] = tri;
      const t0 = { x: getSourceX(sourceMutated[i].x), y: getSourceY(sourceMutated[i].y) };
      const t1 = { x: getSourceX(sourceMutated[j].x), y: getSourceY(sourceMutated[j].y) };
      const t2 = { x: getSourceX(sourceMutated[k].x), y: getSourceY(sourceMutated[k].y) };
      const p0 = { x: getTargetX(targetMutated[i].x), y: getTargetY(targetMutated[i].y) };
      const p1 = { x: getTargetX(targetMutated[j].x), y: getTargetY(targetMutated[j].y) };
      const p2 = { x: getTargetX(targetMutated[k].x), y: getTargetY(targetMutated[k].y) };

      wCtx.save(); wCtx.beginPath();
      const tcX = (p0.x + p1.x + p2.x) / 3;
      const tcY = (p0.y + p1.y + p2.y) / 3;
      const expand = (p: { x: number; y: number }) => {
        const dx = p.x - tcX, dy = p.y - tcY;
        const len = Math.sqrt(dx * dx + dy * dy);
        if (len < 1e-4) return p;
        return { x: p.x + (dx / len) * 1.0, y: p.y + (dy / len) * 1.0 };
      };
      const ep0 = expand(p0), ep1 = expand(p1), ep2 = expand(p2);
      wCtx.moveTo(ep0.x, ep0.y); wCtx.lineTo(ep1.x, ep1.y); wCtx.lineTo(ep2.x, ep2.y);
      wCtx.closePath(); wCtx.clip();

      const det = t0.x * (t1.y - t2.y) - t1.x * (t0.y - t2.y) + t2.x * (t0.y - t1.y);
      if (Math.abs(det) > 1e-6) {
        const i11 = (t1.y - t2.y) / det, i12 = (t2.x - t1.x) / det, i13 = (t1.x * t2.y - t2.x * t1.y) / det;
        const i21 = (t2.y - t0.y) / det, i22 = (t0.x - t2.x) / det, i23 = (t2.x * t0.y - t0.x * t2.y) / det;
        const i31 = (t0.y - t1.y) / det, i32 = (t1.x - t0.x) / det, i33 = (t0.x * t1.y - t1.x * t0.y) / det;
        const a = p0.x * i11 + p1.x * i21 + p2.x * i31, c = p0.x * i12 + p1.x * i22 + p2.x * i32, e = p0.x * i13 + p1.x * i23 + p2.x * i33;
        const b = p0.y * i11 + p1.y * i21 + p2.y * i31, d = p0.y * i12 + p1.y * i22 + p2.y * i32, f = p0.y * i13 + p1.y * i23 + p2.y * i33;
        wCtx.transform(a, b, c, d, e, f);
        wCtx.drawImage(sourceVideo, 0, 0, srcW, srcH);
      }
      wCtx.restore();
    }

    wCtx.globalCompositeOperation = 'destination-in'; wCtx.drawImage(maskCanvas, 0, 0);
    wCtx.globalCompositeOperation = 'source-over';
    ctx.save(); ctx.globalAlpha = opacity; ctx.globalCompositeOperation = blendMode;
    ctx.drawImage(warpCanvas, 0, 0); ctx.restore();
  }

  function startRenderLoop() {
    const render = () => { processFrame(); requestRef.current = requestAnimationFrame(render); };
    requestRef.current = requestAnimationFrame(render);
  }

  function processFrame() {
    const canvas = canvasRef.current, webcam = webcamRef.current, media = uploadedMediaRef.current;
    if (!canvas || !webcam || webcam.readyState < 2) return;
    const ctx = canvas.getContext('2d')!, s = stateRef.current;
    const isMediaActive = s.backgroundMode === 'media' && media;
    const activeBg = isMediaActive ? media : webcam;
    let cW = 0, cH = 0;
    if (activeBg instanceof HTMLVideoElement) { cW = activeBg.videoWidth; cH = activeBg.videoHeight; }
    else if (activeBg instanceof HTMLImageElement) { cW = activeBg.naturalWidth; cH = activeBg.naturalHeight; }

    if (cW > 0 && (canvas.width !== cW)) { canvas.width = cW; canvas.height = cH; }
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    if (activeBg === webcam) {
      ctx.save(); ctx.translate(canvas.width, 0); ctx.scale(-1, 1);
      ctx.drawImage(webcam, 0, 0, canvas.width, canvas.height);
      ctx.restore();
    } else if (cW > 0) {
      ctx.drawImage(activeBg as CanvasImageSource, 0, 0, canvas.width, canvas.height);
    }

    if (webcamCanvasRef.current && webcamCanvasRef.current.width > 0) {
      try { lastWebcamResultRef.current = webcamLandmarkerRef.current?.detect(webcamCanvasRef.current); } catch (e) { }
    }
    if (media && mediaLandmarkerRef.current) {
      const isVideo = media instanceof HTMLVideoElement;
      if (mediaLandmarkerModeRef.current !== (isVideo ? 'VIDEO' : 'IMAGE')) {
        mediaLandmarkerRef.current.setOptions({ runningMode: isVideo ? 'VIDEO' : 'IMAGE' });
        mediaLandmarkerModeRef.current = isVideo ? 'VIDEO' : 'IMAGE';
        return;
      }
      if (isVideo) {
        if ((media as HTMLVideoElement).currentTime !== lastMediaTimeRef.current) {
          try { lastMediaResultRef.current = mediaLandmarkerRef.current?.detectForVideo(media, performance.now()); lastMediaTimeRef.current = (media as HTMLVideoElement).currentTime; } catch (e) { }
        }
      } else try { lastMediaResultRef.current = mediaLandmarkerRef.current?.detect(media as HTMLImageElement); } catch (e) { }
    }

    if (lastWebcamResultRef.current?.faceLandmarks?.[0]) {
      const wM = smoothMarks(lastWebcamResultRef.current.faceLandmarks[0], smoothedWebcamMarksRef);
      if (!media) {
        drawWireframe(ctx, wM, canvas.width, canvas.height, true, baseTriangles);
      }
      const mM = lastMediaResultRef.current?.faceLandmarks?.[0] ? smoothMarks(lastMediaResultRef.current.faceLandmarks[0], smoothedMediaMarksRef) : null;
      if (media && mM) {
        const isMediaBg = s.backgroundMode === 'media';
        const donor = isMediaBg ? (webcamCanvasRef.current || webcam) : media, donorM = isMediaBg ? wM : mM, targetM = isMediaBg ? mM : wM;
        let dW = (donor instanceof HTMLVideoElement) ? donor.videoWidth : (donor instanceof HTMLCanvasElement) ? donor.width : (donor as HTMLImageElement).naturalWidth;
        let dH = (donor instanceof HTMLVideoElement) ? donor.videoHeight : (donor instanceof HTMLCanvasElement) ? donor.height : (donor as HTMLImageElement).naturalHeight;
        if (dW > 0) drawAffineFaceSwap(ctx, donor, donorM, targetM, dW, dH, canvas.width, canvas.height, (activeBg === webcam), false, s.swapEyes, s.swapMouth, s.faceOpacity, s.blendMode, s.maskBlur);
      }
    }
  }

  // --- EFFECTS & HANDLERS ---

  useEffect(() => {
    if (mediaLandmarkerRef.current) {
      mediaLandmarkerRef.current.setOptions({
        minFaceDetectionConfidence: state.faceDetectionConfidence,
        minFacePresenceConfidence: state.facePresenceConfidence,
        minTrackingConfidence: state.faceTrackingConfidence,
      });
    }
  }, [state.faceDetectionConfidence, state.facePresenceConfidence, state.faceTrackingConfidence]);

  useEffect(() => {
    // Inject Tailwind CSS
    if (!document.getElementById('tailwind-cdn')) {
      const script = document.createElement('script');
      script.id = 'tailwind-cdn';
      script.src = 'https://cdn.tailwindcss.com';
      document.head.appendChild(script);
    }

    // Inject Google Fonts
    const fontIds = ['gfont-preconnect-1', 'gfont-preconnect-2', 'gfont-link'];
    if (!document.getElementById(fontIds[0])) {
      const pc1 = document.createElement('link');
      pc1.id = fontIds[0]; pc1.rel = 'preconnect'; pc1.href = 'https://fonts.googleapis.com';
      const pc2 = document.createElement('link');
      pc2.id = fontIds[1]; pc2.rel = 'preconnect'; pc2.href = 'https://fonts.gstatic.com';
      (pc2 as any).crossOrigin = '';
      const link = document.createElement('link');
      link.id = fontIds[2]; link.rel = 'stylesheet';
      link.href = 'https://fonts.googleapis.com/css2?family=Google+Sans:wght@400;500;600;700&family=Google+Sans+Flex:wght@400;500;600;700&family=Google+Sans+Text:wght@400;500;600;700&display=swap';
      document.head.append(pc1, pc2, link);
    }

    const styleTag = document.createElement('style');
    styleTag.textContent = `
      html, body, #root { background: #0e0e0e; font-family: 'Google Sans Text', sans-serif; height: 100%; width: 100%; margin: 0; color: white; overflow: hidden; }
      .scrollbar-hide::-webkit-scrollbar { display: none; }
      input[type=range] { -webkit-appearance: none; appearance: none; background: transparent; width: 100%; cursor: pointer; padding: 8px 0; }
      input[type=range]::-webkit-slider-runnable-track { width: 100%; height: 3px; background: #595959; border-radius: 9999px; }
      input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; appearance: none; width: 14px; height: 14px; border-radius: 50%; background: white; box-shadow: 0px 1px 3px rgba(0,0,0,0.5); margin-top: -5.5px; cursor: grab; }
      @keyframes dropdown-enter { from { opacity: 0; transform: scale(0.95) translateY(-5px); } to { opacity: 1; transform: scale(1) translateY(0); } }
      .animate-dropdown { animation: dropdown-enter 0.15s ease-out forwards; }
    `;
    document.head.appendChild(styleTag);

    let active = true;
    const init = async () => {
      try {
        await faceLandmarkerService.init((s) => { if (active) setState(prev => ({ ...prev, status: s })); });
        webcamLandmarkerRef.current = await faceLandmarkerService.createLandmarker('IMAGE');
        mediaLandmarkerRef.current = await faceLandmarkerService.createLandmarker('IMAGE');

        const canvasEl = document.createElement('canvas');
        webcamCanvasRef.current = canvasEl;
        canvasEl.width = 640; canvasEl.height = 480;
        const flowStream = await Flow.camera.stream({ facingMode: 'user', frameRate: 30, resolution: 'medium' });
        const flowCtx = canvasEl.getContext('2d')!;
        flowStreamRef.current = flowStream;
        flowStream.onFrame(({ bitmap, width, height }: { bitmap: ImageBitmap; width: number; height: number }) => {
          canvasEl.width = width; canvasEl.height = height;
          flowCtx.drawImage(bitmap, 0, 0, width, height);
          bitmap.close();
        });

        if (webcamRef.current && active) {
          const canvasStream = canvasEl.captureStream(30);
          webcamRef.current.srcObject = canvasStream;
          webcamRef.current.onloadeddata = () => {
            if (!active) return;
            webcamRef.current?.play().catch(console.error);
            setState(prev => ({ ...prev, isLoading: false, status: 'Ready' }));
            startRenderLoop();
          };
        }
      } catch (err) {
        console.error("Init Error:", err);
        if (active) setState(prev => ({ ...prev, status: 'Engine Error', isLoading: false }));
      }
    };
    init();

    return () => {
      active = false;
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
      webcamLandmarkerRef.current?.close();
      mediaLandmarkerRef.current?.close();
      if (flowStreamRef.current) flowStreamRef.current.stop();
    };
  }, []);

  const handleMediaSelect = async () => {
    try {
      const media = await Flow.media.select({ filter: 'all' });
      if (!media) return;
      const dataUrl = `data:${media.mimeType};base64,${media.base64}`;
      processNewMedia(dataUrl, media.type === 'video' ? 'video' : 'image');
      setState(prev => ({ ...prev, showOnboarding: false }));
    } catch (err) {
      console.error('Media error:', err);
    }
  };

  const handleGenerateAI = async (prompt: string) => {
    setState(prev => ({ ...prev, isGenerating: true, status: 'Generating AI image...', showOnboarding: false }));
    try {
      const result = await Flow.generate.image({
        prompt,
        modelDisplayName: 'Nano Banana 2',
        aspectRatio: '1:1',
      });
      if (result?.base64) {
        processNewMedia(`data:${result.mimeType};base64,${result.base64}`, 'image');
        setState(prev => ({ ...prev, status: 'Ready' }));
      }
    } catch (err: any) {
      console.error('AI generation error:', err);
      setState(prev => ({ ...prev, status: `AI Error: ${err.message || 'Server error.'}` }));
    } finally {
      setState(prev => ({ ...prev, isGenerating: false }));
    }
  };

  const handleGenerateVideoAI = async (prompt: string) => {
    setState(prev => ({ ...prev, isGenerating: true, status: 'Generating AI video...', showOnboarding: false }));
    try {
      const videoPrompt = `${prompt}, tight cinematic close-up, centered face, stable head position, looking at camera, no camera movement, head stays in frame`;
      const result = await Flow.generate.video({
        prompt: videoPrompt,
        modelDisplayName: 'Veo 3.1 - Lite',
        aspectRatio: '16:9',
        durationSeconds: 8,
      });
      if (result?.base64) {
        processNewMedia(`data:${result.mimeType};base64,${result.base64}`, 'video');
        setState(prev => ({ ...prev, status: 'Ready' }));
      }
    } catch (err: any) {
      console.error('AI video generation error:', err);
      setState(prev => ({ ...prev, status: `AI Error: ${err.message || 'Server error.'}` }));
    } finally {
      setState(prev => ({ ...prev, isGenerating: false }));
    }
  };

  const validateFaceInMedia = (element: HTMLImageElement | HTMLVideoElement) => {
    try {
      const landmarker = mediaLandmarkerRef.current;
      if (!landmarker) return;
      landmarker.setOptions({ runningMode: 'IMAGE' });
      mediaLandmarkerModeRef.current = 'IMAGE';
      let res;
      if (element instanceof HTMLVideoElement) {
        const tmpCanvas = document.createElement('canvas');
        tmpCanvas.width = element.videoWidth; tmpCanvas.height = element.videoHeight;
        tmpCanvas.getContext('2d')!.drawImage(element, 0, 0);
        res = landmarker.detect(tmpCanvas);
      } else {
        res = landmarker.detect(element);
      }
      setState(prev => ({ ...prev, mediaFaceWarning: !res?.faceLandmarks?.length }));
    } catch (e) { console.error(e); }
  };

  const processNewMedia = (dataUrl: string, type: 'image' | 'video') => {
    if (uploadedMediaRef.current instanceof HTMLVideoElement) {
      uploadedMediaRef.current.pause();
      uploadedMediaRef.current.src = "";
      uploadedMediaRef.current.load();
    }
    setState(prev => ({ ...prev, mediaFaceWarning: false }));
    if (type === 'image') {
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.src = dataUrl;
      img.onload = () => {
        uploadedMediaRef.current = img;
        setState(prev => ({ ...prev, hasMedia: true }));
        setTimeout(() => validateFaceInMedia(img), 100);
      };
    } else {
      const vid = document.createElement('video');
      vid.src = dataUrl;
      vid.crossOrigin = 'anonymous';
      vid.loop = true; vid.playsInline = true;
      vid.onloadeddata = () => {
        vid.play().catch(console.error);
        uploadedMediaRef.current = vid;
        setState(prev => ({ ...prev, hasMedia: true }));
        setTimeout(() => validateFaceInMedia(vid), 200);
      };
    }
  };

  const handleSave = async () => {
    if (!canvasRef.current) return;
    try {
      const base64 = canvasRef.current.toDataURL('image/png').split(',')[1];
      await Flow.save({ base64, mimeType: 'image/png', name: '3D Face Swap' });
    } catch (err) { console.error(err); }
  };

  const handleToggleRecording = async () => {
    if (!state.hasMedia) return;
    if (state.isRecording) stopRecording(); else await startRecording();
  };

  const startRecording = async () => {
    if (!canvasRef.current) return;
    try {
      setState(prev => ({ ...prev, isRecording: true, status: 'Recording...' }));
      recordedChunksRef.current = [];
      const stream = canvasRef.current.captureStream(30);
      const options: MediaRecorderOptions = { mimeType: 'video/webm;codecs=vp9,opus', videoBitsPerSecond: 2_500_000 };
      if (!MediaRecorder.isTypeSupported(options.mimeType!)) options.mimeType = 'video/webm';
      const recorder = new MediaRecorder(stream, options);
      recorder.ondataavailable = (e) => { if (e.data.size > 0) recordedChunksRef.current.push(e.data); };
      recorder.onstop = async () => {
        setState(prev => ({ ...prev, isRecording: false, isProcessing: true, status: 'Transcoding...' }));
        const webmBlob = new Blob(recordedChunksRef.current, { type: 'video/webm' });
        try {
          // 1. Performance Recorder: Live state capture with MediaBunny transcoding to valid MP4
          const input = new Input({ source: new BlobSource(webmBlob), formats: ALL_FORMATS });
          const output = new Output({
            format: new Mp4OutputFormat({ fastStart: 'in-memory' }),
            target: new BufferTarget(),
          });
          const conversion = await Conversion.init({ input, output });
          if (!conversion.isValid) throw new Error("Transcoding failed");
          await conversion.execute();
          const mp4Buffer = output.target.buffer!;

          // 2. Surgical Fix: Loop-based base64 building to prevent stack overflow
          const bytes = new Uint8Array(mp4Buffer);
          let binary = '';
          for (let i = 0; i < bytes.byteLength; i++) { binary += String.fromCharCode(bytes[i]); }
          const base64 = btoa(binary);

          // 3. Surgical Fix: Compiler-safe character splitting (no Regex)
          const isSafe = (char: string) => "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-".includes(char);
          const sanitizedName = `FaceSwap_${Date.now()}`.split('').filter(isSafe).join('');

          try {
            // 4. Save to Grid
            await Flow.save({ base64, mimeType: 'video/mp4', name: sanitizedName });
            setState(prev => ({ ...prev, isProcessing: false, status: 'Saved!' }));
          } catch (uploadErr) {
            console.error('Flow.save failed, using download fallback:', uploadErr);
            // Secure fallback
            await Flow.download({ base64, mimeType: 'video/mp4', filename: `${sanitizedName}.mp4` });
            setState(prev => ({ ...prev, isProcessing: false, status: 'Downloaded!' }));
          }
          setTimeout(() => setState(prev => ({ ...prev, status: 'Ready' })), 2000);
        } catch (err) {
          console.error('Processing error:', err);
          setState(prev => ({ ...prev, isProcessing: false, status: 'Error' }));
        }
      };
      mediaRecorderRef.current = recorder; recorder.start(100);
    } catch (err) { console.error('Recording error:', err); setState(prev => ({ ...prev, isRecording: false, status: 'Recording failed' })); }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') mediaRecorderRef.current.stop();
  };

  return (
    <div className="flex h-screen w-screen bg-[#0e0e0e] overflow-hidden">
