class FaceLandmarkerService {
  private vision: any = null;

  async init(onStatus?: (status: string) => void) {
    if (this.vision) return;

    onStatus?.('Loading MediaPipe Fileset...');
    // FilesetResolver is a static utility to locate the WASM binaries
    this.vision = await FilesetResolver.forVisionTasks(
      'https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.3/wasm'
    );
  }

  async createLandmarker(mode: 'IMAGE' | 'VIDEO' = 'VIDEO') {
    if (!this.vision) throw new Error('Vision not initialized');

    return await FaceLandmarker.createFromOptions(this.vision, {
      baseOptions: {
        modelAssetPath: 'https://storage.googleapis.com/mediapipe-models/face_landmarker/face_landmarker/float16/1/face_landmarker.task',
        delegate: 'GPU',
      },
      runningMode: mode,
      numFaces: 1,
      minFaceDetectionConfidence: 0.3,
      minFacePresenceConfidence: 0.3,
      minTrackingConfidence: 0.3,
      outputFacialTransformationMatrixes: true,
      outputFaceBlendshapes: true,
    });
  }
}

