/**
 * Pre-computed triangle list from MediaPipe's face mesh tessellation.
 * Uses a more robust adjacency check to ensure the mesh is fully populated.
 */
export const getFaceTriangles = (): number[][] => {
  const edges = FaceLandmarker.FACE_LANDMARKS_TESSELATION;
  const adj = new Map<number, Set<number>>();

  // Build adjacency list safely
  edges.forEach(edge => {
    if (!adj.has(edge.start)) adj.set(edge.start, new Set());
    if (!adj.has(edge.end)) adj.set(edge.end, new Set());
    adj.get(edge.start)!.add(edge.end);
    adj.get(edge.end)!.add(edge.start);
  });

  const triangles: number[][] = [];
  const seen = new Set<string>();

  // Find all triangles (3-cycles) in the tessellation graph
  edges.forEach(edge => {
    const u = edge.start;
    const v = edge.end;
    const neighborsU = adj.get(u);
    const neighborsV = adj.get(v);

    if (neighborsU && neighborsV) {
      for (const w of neighborsU) {
        if (neighborsV.has(w)) {
          const tri = [u, v, w].sort((a, b) => a - b);
          const key = tri.join(',');
          if (!seen.has(key)) {
            triangles.push(tri);
            seen.add(key);
          }
        }
      }
    }
  });

  return triangles;
};

